// src/engine/font.ts
var ALIASES = { "\u2190": "\u2190", "\xA9": "\xA9", "a": "A" };
var BitmapFont = class {
  constructor(img, meta) {
    this.img = img;
    this.meta = meta;
  }
  /** width of `text` in px at scale 1 */
  width(text, spacing = 0) {
    return text.length * (this.meta.cell + spacing) - spacing;
  }
  draw(ctx, text, x, y, variant = "white", scale = 1, spacing = 0) {
    const vi = Math.max(0, this.meta.variants.indexOf(variant));
    const cell = this.meta.cell;
    const upper = text.toUpperCase();
    let cx = Math.round(x);
    const cy = Math.round(y);
    for (const ch0 of upper) {
      const ch = ALIASES[ch0] ?? ch0;
      const g = this.meta.glyphs[ch];
      if (g) {
        ctx.drawImage(this.img, g[0], g[1] + vi * this.meta.variantStride, cell, cell, cx, cy, cell * scale, cell * scale);
      }
      cx += (cell + spacing) * scale;
    }
  }
  /** centred text */
  drawCentered(ctx, text, cx, y, variant = "white", scale = 1, spacing = 0) {
    const w = this.width(text, spacing) * scale;
    this.draw(ctx, text, Math.round(cx - w / 2), y, variant, scale, spacing);
  }
  /** big blue timer digits (14 px) */
  drawBig(ctx, text, x, y, scale = 1) {
    let cx = Math.round(x);
    for (const ch of text) {
      const d = this.meta.bigDigits[ch];
      if (d) {
        ctx.drawImage(this.img, d[0], d[1], d[2], d[3], cx, Math.round(y), d[2] * scale, d[3] * scale);
        cx += (d[2] - 1) * scale;
      } else {
        cx += 8 * scale;
      }
    }
    return cx;
  }
  bigWidth(text, scale = 1) {
    let w = 0;
    for (const ch of text) {
      const d = this.meta.bigDigits[ch];
      w += (d ? d[2] - 1 : 8) * scale;
    }
    return w;
  }
};
function fmtScore(n) {
  const v = Math.max(0, Math.floor(n));
  return v < 10 ? `0${v}` : v.toLocaleString("en-US");
}
function fmtTime(sec) {
  const s = Math.max(0, Math.min(99, Math.floor(sec)));
  return s < 10 ? `0${s}` : String(s);
}

// src/engine/assets.ts
var ASSET_ROOT = "/assets/";
function loadImage(src) {
  return new Promise((res, rej) => {
    const img = new Image();
    img.onload = () => res(img);
    img.onerror = () => rej(new Error(`failed to load ${src}`));
    img.src = src;
  });
}
var Assets = class {
  sheets;
  font;
  stages = /* @__PURE__ */ new Map();
  async load(onProgress) {
    const names = ["marble", "marbleRed", "worm", "slime", "bird", "hammer", "vacuum", "objects"];
    const files = {
      marble: "sprites/marble_effects.png",
      marbleRed: "sprites/marble_effects_red.png",
      worm: "sprites/worm.png",
      slime: "sprites/slime.png",
      bird: "sprites/bird.png",
      hammer: "sprites/hammer.png",
      vacuum: "sprites/vacuum.png",
      objects: "sprites/objects.png"
    };
    let done = 0;
    const total = names.length + 2;
    const tick = () => {
      done++;
      onProgress?.(done / total);
    };
    const imgs = await Promise.all(names.map(async (n) => {
      const im = await loadImage(ASSET_ROOT + files[n]);
      tick();
      return im;
    }));
    this.sheets = Object.fromEntries(names.map((n, i) => [n, imgs[i]]));
    const [fontImg, fontMeta] = await Promise.all([
      loadImage(ASSET_ROOT + "sprites/font.png"),
      fetch(ASSET_ROOT + "sprites/font.json").then((r) => r.json())
    ]);
    tick();
    tick();
    this.font = new BitmapFont(fontImg, fontMeta);
  }
  async stage(image) {
    let im = this.stages.get(image);
    if (!im) {
      im = await loadImage(ASSET_ROOT + image);
      this.stages.set(image, im);
    }
    return im;
  }
};
function drawFrame(ctx, img, f, x, y, flipX = false) {
  const dx = Math.round(x - f.px), dy = Math.round(y - f.py);
  if (!flipX) {
    ctx.drawImage(img, f.x, f.y, f.w, f.h, dx, dy, f.w, f.h);
  } else {
    ctx.save();
    ctx.translate(Math.round(x + f.px), dy);
    ctx.scale(-1, 1);
    ctx.drawImage(img, f.x, f.y, f.w, f.h, 0, 0, f.w, f.h);
    ctx.restore();
  }
}

